CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, password TEXT NOT NULL, verified INTEGER, role TEXT NOT NULL DEFAULT 'user' CHECK (role IN ('user','admin','owner')), created INTEGER NOT NULL);
CREATE UNIQUE INDEX one_owner ON users(role) WHERE role = 'owner';
CREATE TABLE tokens (hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX tokens_user ON tokens(user_id,kind);
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE audit_log (id INTEGER PRIMARY KEY, user_id TEXT REFERENCES users(id), event TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL);
CREATE TABLE subscriptions (user_id TEXT PRIMARY KEY REFERENCES users(id), plan TEXT NOT NULL, expires INTEGER NOT NULL, renew INTEGER NOT NULL DEFAULT 0);
CREATE TABLE payment_events (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), plan TEXT NOT NULL, amount INTEGER NOT NULL, mode TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE quota_usage (user_id TEXT NOT NULL REFERENCES users(id), feature TEXT NOT NULL, period TEXT NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(user_id,feature,period));
CREATE TABLE quota_overrides (user_id TEXT NOT NULL REFERENCES users(id), feature TEXT NOT NULL, maximum INTEGER NOT NULL, PRIMARY KEY(user_id,feature));
CREATE TABLE jobs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), query TEXT NOT NULL, state TEXT NOT NULL, progress INTEGER NOT NULL DEFAULT 0, attempts INTEGER NOT NULL DEFAULT 0, run_after INTEGER NOT NULL, lease TEXT, message TEXT, result TEXT, created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE INDEX jobs_work ON jobs(state,run_after);
CREATE INDEX jobs_owner ON jobs(user_id,created);
CREATE TABLE saved_searches (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), label TEXT NOT NULL, query TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE leads (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), source TEXT NOT NULL, source_id TEXT NOT NULL, fingerprint TEXT NOT NULL, data TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'new', favorite INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, UNIQUE(user_id,source,source_id), UNIQUE(user_id,fingerprint));
CREATE TABLE stores (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), platform TEXT NOT NULL, name TEXT NOT NULL, credential TEXT, status TEXT NOT NULL, created INTEGER NOT NULL, synced INTEGER, error TEXT, UNIQUE(user_id,platform,name));
CREATE TABLE lots (store_id TEXT NOT NULL REFERENCES stores(id) ON DELETE CASCADE, external_id TEXT NOT NULL, title TEXT NOT NULL, price INTEGER NOT NULL, status TEXT NOT NULL, PRIMARY KEY(store_id,external_id));
CREATE TABLE orders (store_id TEXT NOT NULL REFERENCES stores(id) ON DELETE CASCADE, external_id TEXT NOT NULL, title TEXT NOT NULL, amount INTEGER NOT NULL, commission INTEGER, cost INTEGER, status TEXT NOT NULL, created INTEGER NOT NULL, PRIMARY KEY(store_id,external_id));
CREATE TABLE inventory (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), label TEXT NOT NULL, secret TEXT NOT NULL, created INTEGER NOT NULL, store_id TEXT, order_id TEXT, state TEXT NOT NULL DEFAULT 'available', FOREIGN KEY(store_id,order_id) REFERENCES orders(store_id,external_id), UNIQUE(store_id,order_id));
CREATE TABLE templates (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), title TEXT NOT NULL, body TEXT NOT NULL);
CREATE TABLE price_rules (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), store_id TEXT NOT NULL, lot TEXT NOT NULL, min INTEGER NOT NULL, max INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE telegram (user_id TEXT PRIMARY KEY REFERENCES users(id), token TEXT NOT NULL, chat TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1);
